from openpyxl import load_workbook
from openpyxl.styles import Font

wb = load_workbook(INPUT_PATH)
ws = wb["零件清單"]

# 建立欄名對照
headers = [cell.value for cell in ws[1]]
header_map = {name: idx for idx, name in enumerate(headers)}

# 依項次分組，收集列與料件屬性
groups = {}
for row in ws.iter_rows(min_row=2, values_only=False):
    values = [cell.value for cell in row]
    item_no = values[header_map["項次"]]
    attr = values[header_map["料件屬性"]]

    if item_no not in groups:
        groups[item_no] = {"rows": [], "attrs": set()}
    groups[item_no]["rows"].append(row)
    if attr:
        groups[item_no]["attrs"].add(attr)

# 挑出同時有 M 與 S 的整組列
matching_rows = []
for group in groups.values():
    if "M" in group["attrs"] and "S" in group["attrs"]:
        matching_rows.extend(group["rows"])

# 建立新工作表，欄位與原表相同
new_ws = wb.create_sheet(title="M_S同組項次")

# 複製表頭並保留粗體格式
for col_idx, header_cell in enumerate(ws[1], start=1):
    new_cell = new_ws.cell(row=1, column=col_idx, value=header_cell.value)
    if header_cell.font.bold:
        new_cell.font = Font(bold=True)

# 複製符合條件的資料列
for row_idx, row in enumerate(matching_rows, start=2):
    for col_idx, cell in enumerate(row, start=1):
        new_ws.cell(row=row_idx, column=col_idx, value=cell.value)

wb.save(OUTPUT_PATH)
```

