# 推斷：資料表=零件清單（表頭第1~2列）｜欄位=項次、料號、品名、耐候｜主檔=零件清單｜鍵=項次｜篩選=耐候≠OK｜輸出=新工作表「耐候異常」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws = wb["零件清單"]

# 定位表頭：第1列為主標頭，第2列為 E~G 副標頭（含「耐候」）
header_row = None
subheader_row = None
for r in range(1, min(5, ws.max_row + 1)):
    if ws.cell(r, 1).value == "項次":
        header_row = r
        # 檢查下一列是否包含「耐候」等副標頭
        if r + 1 <= ws.max_row:
            for c in range(1, ws.max_column + 1):
                if ws.cell(r + 1, c).value == "耐候":
                    subheader_row = r + 1
                    break
        break

if header_row is None:
    header_row = 1
    subheader_row = 2

# 建立欄名→欄號對照
header_map = {}
for c in range(1, ws.max_column + 1):
    v1 = ws.cell(header_row, c).value
    v2 = ws.cell(subheader_row, c).value if subheader_row else None
    if v1:
        header_map[v1] = c
    if v2:
        header_map[v2] = c

required = ["項次", "料號", "品名", "耐候"]
missing = [h for h in required if h not in header_map]
if missing:
    raise ValueError(f"缺少必要欄位：{missing}")

data_start = (subheader_row if subheader_row else header_row) + 1

# 篩選「耐候」不是「OK」的資料
filtered = []
for r in range(data_start, ws.max_row + 1):
    weather = ws.cell(r, header_map["耐候"]).value
    if weather is None or str(weather).strip() != "OK":
        filtered.append([ws.cell(r, header_map[h]).value for h in required])

# 建立新工作表
new_title = "耐候異常"
if new_title in wb.sheetnames:
    del wb[new_title]
ws_new = wb.create_sheet(title=new_title)

# 寫入標頭
for c, h in enumerate(required, 1):
    ws_new.cell(1, c, h)

# 寫入篩選結果
for r_idx, row_vals in enumerate(filtered, 2):
    for c_idx, val in enumerate(row_vals, 1):
        ws_new.cell(r_idx, c_idx, val)

wb.save(OUTPUT_PATH)
```

